INSERT INTO contract_variables (id, name, label, description, created_at) VALUES (18, 'start_date', '开工日期', NULL, '2026-06-03 02:22:16');
INSERT INTO contract_variables (id, name, label, description, created_at) VALUES (19, 'end_date', '完工日期', NULL, '2026-06-03 02:22:16');
INSERT INTO contract_variables (id, name, label, description, created_at) VALUES (20, 'company_address', '公司地址', NULL, '2026-06-03 02:22:16');
