INSERT INTO main_materials (id, cover_image, code, name, brand, specification, model, color, category, quote_unit, original_price, quote_price, cost_price, contract_price, package_name, leak_detection, gift_item, optional_item, remark, acceptance_remark, contract_remark, other_remark, is_visible, is_fixed, sort_order, created_at, updated_at, cost_price2, exchange_rate, purchase_unit, loss_rate, loss_amount, warranty_period, stock_period, spec_alternative, model_alternative, color_alternative, position, upgrade_profit_rate, internal_control_price, combo, limit_formula, quote_formula) VALUES (433, NULL, '2839', '浅紫色LR-PERT I（适用于集中供暖系统）', '', '', '', '', '伟星', 'm²', 0, 120, 0, 0, '', '不检测', '否', '否', '内表面光滑，延长清洗周期。内表面光滑平整，水流阻力小，流速快，不易粘附污垢，在换热效率大幅提高的同时，更有效延长清洗周期，减少频繁清洗对对地暖管造成的损伤，进而提升地暖管材的寿命和采暖效率。水压损失小，节能高效。LR-PERT地暖管内表面在2000倍显微镜下,粗糙度相当于普通PERT的0.1倍，管道内表面基本没有凸起和凹陷的部分，从而大幅减少了水压损失，提高水能、热能的利用率，节能高效采暖舒适。', '', '', '', 1, 0, 0, '2026-04-13 03:13:27', '2026-04-13 03:13:27', 85, 1, 'm²', 0, 0, '0', '0', '', '', '', '', 0, 0, '0', '', '');
